<script setup lang="ts">
import {computed,onBeforeUnmount,ref,shallowRef,watch} from 'vue';
import {api,ApiError} from '../api';
import type {InterimCandidate,InterimDocument,InterimPage} from '../contracts';
import {interimPage,interimDocument} from '../utils/interim-findings';
import {absoluteTime} from '../utils/time';
import Button from './ui/Button.vue';
import Select from './ui/Select.vue';
import InterimReviewPanel from './InterimReviewPanel.vue';
import {useAuth} from '../composables/auth';
const {canOperate}=useAuth();
const selection=ref<InterimCandidate[]>([]),severity=ref(''),duplicates=ref('');
function selectCandidate(c:InterimCandidate){const index=selection.value.findIndex(v=>v.id===c.id&&v.artifact===c.artifact);if(index>=0)selection.value.splice(index,1);else selection.value.push(c)}
import Input from './ui/Input.vue';
const props=defineProps<{scanId:number;attempt:number;sourceHash:string;running:boolean}>();
const snapshot=shallowRef<InterimPage|null>(null),selected=shallowRef<InterimCandidate|null>(null),document=shallowRef<InterimDocument|null>(null);
const downloading=ref(false);
const loading=ref(false),error=ref(''),evidenceError=ref(''),reading=ref(false),search=ref(''),page=ref(1),documentPage=ref(1),expanded=ref(true),showDocuments=ref(false),selectedArtifact=ref('');
let epoch=0,evidenceEpoch=0,disposed=false,timer:ReturnType<typeof setTimeout>|undefined,searchTimer:ReturnType<typeof setTimeout>|undefined;
const pages=computed(()=>Math.max(1,Math.ceil((snapshot.value?.total??0)/20)));
async function load(){const gen=++epoch,id=props.scanId,attempt=props.attempt;loading.value=true;error.value='';try{const v=interimPage(await api.interimFindings(id,attempt,{page:page.value,pageSize:20,search:search.value,documentPage:documentPage.value,severity:severity.value,duplicates:duplicates.value}),id,attempt,props.sourceHash);if(disposed||gen!==epoch)return;if(!v)throw new Error('中间发现的合同、执行或源码身份不匹配，已拒绝展示。');snapshot.value=v;}catch(e){if(!disposed&&gen===epoch)error.value=e instanceof ApiError&&e.status===404?'此版本或历史执行尚未提供中间发现；最终报告与原始会话仍可读取。':(e as Error).message;}finally{if(!disposed&&gen===epoch){loading.value=false;clearTimeout(timer);if(props.running)timer=setTimeout(()=>void load(),4000)}}}
async function readEvidence(artifact:string,candidate:InterimCandidate|null=null){const gen=++evidenceEpoch,id=props.scanId,attempt=props.attempt;selected.value=candidate;selectedArtifact.value=artifact;document.value=null;evidenceError.value='';reading.value=true;try{const v=interimDocument(await api.interimEvidence(id,attempt,artifact),id,attempt,props.sourceHash);if(disposed||gen!==evidenceEpoch)return;if(!v)throw new Error('中间证据的执行或源码身份不匹配');const known=snapshot.value?.documents.find(d=>d.artifact.sha256===artifact);if(known&&(known.sourceSha256!==v.sourceSha256||known.sourcePath!==v.sourcePath))throw new Error('中间证据来源与索引不一致');document.value=v;}catch(e){if(!disposed&&gen===evidenceEpoch)evidenceError.value=(e as Error).message;}finally{if(!disposed&&gen===evidenceEpoch)reading.value=false}}
function closeEvidence(){evidenceEpoch++;selected.value=null;selectedArtifact.value='';document.value=null;reading.value=false;evidenceError.value=''}
async function download(){if(!document.value||downloading.value)return;const gen=evidenceEpoch,id=props.scanId,attempt=props.attempt,artifact=selectedArtifact.value;downloading.value=true;try{const blob=await api.interimEvidenceDownload(id,attempt,artifact);if(disposed||gen!==evidenceEpoch)return;const url=URL.createObjectURL(blob),a=window.document.createElement('a');a.href=url;a.download=`interim-evidence-attempt-${attempt}-${artifact}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(e){if(!disposed&&gen===evidenceEpoch)evidenceError.value='证据下载失败：'+(e as Error).message;}finally{downloading.value=false}}
function move(next:number){page.value=next;void load()}
watch(()=>[props.scanId,props.attempt,props.sourceHash],()=>{epoch++;clearTimeout(timer);clearTimeout(searchTimer);snapshot.value=null;search.value='';selection.value=[];severity.value='';duplicates.value='';page.value=1;documentPage.value=1;error.value='';closeEvidence();if(props.attempt>0)void load()},{immediate:true});
watch(()=>props.running,()=>void load());
watch(search,()=>{clearTimeout(searchTimer);searchTimer=setTimeout(()=>{page.value=1;void load()},300)});
watch([severity,duplicates],()=>{page.value=1;void load()});
onBeforeUnmount(()=>{disposed=true;epoch++;evidenceEpoch++;clearTimeout(timer);clearTimeout(searchTimer)});
</script>
<template>
 <section id="interim-findings" class="interim-findings" aria-label="Standard 中间发现">
  <header class="interim-header"><button type="button" class="section-toggle" :aria-expanded="expanded" @click="expanded=!expanded">中间发现 <span>候选记录 · 未最终汇总</span></button><Button size="sm" variant="ghost" :disabled="loading" @click="load">刷新中间发现</Button></header>
  <template v-if="expanded">
   <p class="interim-note">第 {{attempt}} 次执行 · 候选记录与最终结果分别保存，可能重复或被后续推翻，不计入最终漏洞数量。<template v-if="running"> 每 4 秒读取已保存快照。</template></p>
   <p v-if="error" role="alert" class="interim-error">{{error}}<Button size="sm" variant="ghost" :disabled="loading" @click="load">重新读取中间发现</Button></p>
   <p v-if="loading&&!snapshot" role="status">正在读取已保存的中间证据…</p>
   <template v-if="snapshot">
    <p class="interim-note" role="status">{{snapshot.reason}}<template v-if="snapshot.observedAt"> 最近保存 {{absoluteTime(snapshot.observedAt)}} · {{snapshot.total}} 条匹配候选记录 · {{snapshot.documentTotal}} 份证据版本。</template></p>
    <p v-if="snapshot.issues.length" class="interim-error" role="alert">{{snapshot.issues.join(' ')}}</p>
    <template v-if="snapshot.state!=='unavailable'">
     <div class="interim-toolbar"><Input v-model="search" aria-label="搜索中间候选发现" placeholder="搜索候选标题、描述或证据位置…"/><Select v-model="severity" :options="['critical','high','medium','low','info'].map(v=>({value:v,label:v}))" clearable placeholder="全部模型初评" aria-label="候选模型初评"/><Select v-model="duplicates" :options="[{value:'collapse',label:'折叠精确重复'},{value:'only',label:'仅看精确重复'}]" clearable placeholder="全部候选记录" aria-label="候选精确去重"/><Button size="sm" variant="outline" :aria-expanded="showDocuments" @click="showDocuments=!showDocuments">{{showDocuments?'收起':'查看'}}证据文件</Button></div>
     <div v-if="showDocuments" class="interim-documents" role="region" aria-label="中间证据文件"><ul><li v-for="d in snapshot.documents" :key="d.artifact.sha256"><button type="button" @click="readEvidence(d.artifact.sha256)">{{d.label}} <span>{{d.candidateCount}} 条候选记录</span></button><code>{{d.sourcePath}}</code></li></ul><nav v-if="snapshot.documentTotal>50" aria-label="中间证据文件分页"><Button size="sm" variant="outline" :disabled="loading||documentPage<=1" @click="documentPage--;load()">上一页证据</Button><span>第 {{documentPage}} 页</span><Button size="sm" variant="outline" :disabled="loading||documentPage*50>=snapshot.documentTotal" @click="documentPage++;load()">下一页证据</Button></nav></div>
     <div class="interim-workspace" :class="{'with-evidence':!!selectedArtifact}">
      <div class="interim-list"><div class="interim-table"><table><thead><tr><th>候选发现</th><th>模型初评</th><th>证据引用</th></tr></thead><tbody><tr v-for="item in snapshot.items" :key="item.id" :class="{selected:selected?.id===item.id}"><td><input v-if="canOperate" type="checkbox" :aria-label="'选择候选 '+item.title" :checked="selection.some(v=>v.id===item.id&&v.artifact===item.artifact)" @change="selectCandidate(item)"/><button type="button" :aria-pressed="selected?.id===item.id" @click="readEvidence(item.artifact,item)">{{item.title}}</button><span class="candidate-state">候选 · 未验证</span></td><td>{{item.reportedSeverity??'未提供'}}</td><td class="candidate-location">{{item.evidence[0]??'查看原始检查点'}}</td></tr></tbody></table></div>
       <p v-if="!snapshot.items.length" class="interim-note">{{search?'没有匹配的候选记录。':'已保存证据中尚无可结构化的候选记录；这不代表扫描已完成或没有漏洞。'}}</p>
       <nav class="interim-pagination" aria-label="中间发现分页"><span>第 {{page}} / {{pages}} 页</span><Button size="sm" variant="outline" :disabled="loading||page<=1" @click="move(page-1)">上一页候选</Button><Button size="sm" variant="outline" :disabled="loading||page>=pages" @click="move(page+1)">下一页候选</Button></nav>
      </div>
      <aside v-if="selectedArtifact" class="interim-inspector" aria-label="中间证据详情"><header><h3>{{selected?.title??'中间证据文件'}}</h3><Button size="sm" variant="ghost" @click="closeEvidence">关闭中间证据</Button></header><p class="interim-note">模型观察与推断，未作为最终结果；原文中的“确认”等表述仍属于模型声明。</p><p v-if="reading" role="status">正在校验证据…</p><p v-if="evidenceError" role="alert" class="interim-error">{{evidenceError}}<Button size="sm" variant="ghost" @click="readEvidence(selectedArtifact,selected)">重新读取证据</Button></p>
       <template v-if="document"><p v-if="selected?.summary">{{selected.summary}}</p><dl><div><dt>来源标识</dt><dd>{{document.sourcePath}}</dd></div><div><dt>保存时间</dt><dd>{{absoluteTime(document.observedAt)}}</dd></div><div><dt>原始内容 SHA-256</dt><dd><code>{{document.sourceSha256}}</code></dd></div><div><dt>展示副本 SHA-256</dt><dd><code>{{selectedArtifact}}</code></dd></div><div><dt>冻结源码</dt><dd><code>{{sourceHash}}</code></dd></div><div v-if="document.threadId"><dt>Worker 会话</dt><dd>{{document.threadId}}</dd></div></dl><ul v-if="selected?.evidence.length" class="candidate-evidence"><li v-for="(e,i) in selected.evidence" :key="i"><code>{{e}}</code></li></ul><p v-if="selected?.omittedEvidence||selected?.truncated||document.truncated" class="interim-note">摘要展示不完整，请核查原文及原始会话。</p><Button size="sm" variant="outline" :loading="downloading" :disabled="downloading" @click="download">下载脱敏证据 JSON</Button><details><summary>查看检查点原文（已脱敏）</summary><pre>{{document.content}}</pre></details></template>
      </aside>
     </div>
     <InterimReviewPanel :scan-id="scanId" :attempt="attempt" :running="running" :selected="selection" @clear="selection=[]"/>
    </template>
   </template>
  </template>
 </section>
</template>
<style scoped>
.interim-findings{min-width:0;border-block:1px solid var(--border-default);margin-block:var(--space-4);padding-block:var(--space-3);font-size:var(--font-size-sm)}.interim-header,.interim-toolbar,.interim-pagination,aside header,nav{display:flex;align-items:center;gap:var(--space-2);flex-wrap:wrap}.interim-header{justify-content:space-between}.section-toggle{text-align:start;font-weight:var(--font-weight-medium);color:var(--text-primary)}.section-toggle span{margin-inline-start:var(--space-2);font-weight:var(--font-weight-normal);color:var(--text-secondary)}.interim-note{margin-block:var(--space-2);color:var(--text-secondary);line-height:var(--line-height-body);overflow-wrap:anywhere}.interim-error{color:var(--state-danger);margin-block:var(--space-2)}.interim-toolbar{margin-block:var(--space-3)}.interim-toolbar input{max-width:440px;flex:1;min-width:0}.interim-workspace{display:grid;grid-template-columns:minmax(0,1fr);min-width:0}.interim-workspace.with-evidence{grid-template-columns:minmax(0,1fr) minmax(280px,.85fr)}.interim-list{min-width:0}.interim-table{max-height:440px;overflow:auto}table{width:100%;border-collapse:collapse;table-layout:fixed;text-align:start}th,td{padding:var(--space-2);border-bottom:1px solid var(--border-subtle);vertical-align:top;overflow-wrap:anywhere}th{font-weight:var(--font-weight-medium);color:var(--text-secondary)}th:first-child{width:50%}th:nth-child(2){width:15%}td button{color:var(--accent-primary);text-align:start;line-height:var(--line-height-body)}tr:hover{background:var(--surface-hover)}tr.selected{background:var(--surface-selected)}.candidate-state{display:block;font-size:var(--font-size-xs);color:var(--text-secondary);margin-top:var(--space-1)}.candidate-location{font-family:var(--font-mono);font-size:var(--font-size-xs)}.interim-pagination{justify-content:flex-end;margin-top:var(--space-2);color:var(--text-secondary)}.interim-inspector{min-width:0;border-inline-start:1px solid var(--border-default);padding-inline-start:var(--space-3);margin-inline-start:var(--space-3);max-height:620px;overflow:auto}.interim-inspector header{align-items:flex-start;justify-content:space-between}.interim-inspector h3{font-size:var(--font-size-sm);font-weight:var(--font-weight-medium);margin:0;flex:1;overflow-wrap:anywhere}.interim-inspector p{line-height:var(--line-height-body);overflow-wrap:anywhere}dl{margin-block:var(--space-3)}dl>div{display:grid;grid-template-columns:110px minmax(0,1fr);gap:var(--space-2);padding-block:var(--space-1)}dt{color:var(--text-secondary)}dd{margin:0;overflow-wrap:anywhere}code,pre{font-family:var(--font-mono);font-size:var(--font-size-xs);white-space:pre-wrap;overflow-wrap:anywhere}.candidate-evidence{padding-inline-start:var(--space-4);margin-block:var(--space-3)}summary{cursor:pointer;margin-block:var(--space-2)}pre{padding:var(--space-2);background:var(--surface-secondary);max-height:360px;overflow:auto}.interim-documents{border-block:1px solid var(--border-subtle);padding-block:var(--space-2);margin-bottom:var(--space-3)}.interim-documents ul{padding:0;margin:0;list-style:none;max-height:240px;overflow:auto}.interim-documents li{display:flex;flex-wrap:wrap;gap:var(--space-2);padding-block:var(--space-1)}.interim-documents button{color:var(--accent-primary);text-align:start}.interim-documents span{color:var(--text-secondary);font-size:var(--font-size-xs)}button:focus-visible{outline:2px solid var(--border-focus);outline-offset:2px}@media(max-width:1000px){.interim-workspace.with-evidence{grid-template-columns:minmax(0,1fr)}.interim-inspector{border-inline-start:0;border-top:1px solid var(--border-default);padding-inline-start:0;padding-top:var(--space-3);margin-inline-start:0;margin-top:var(--space-3);max-height:none}}@media(max-width:640px){th:first-child{width:58%}th:nth-child(2){width:20%}.interim-toolbar input{flex-basis:100%;max-width:none}.interim-header{align-items:flex-start}.section-toggle span{display:block;margin-inline-start:0;margin-top:var(--space-1)}dl>div{grid-template-columns:1fr;gap:var(--space-1)}}
</style>
